mapper.select:
SELECT DISTINCT C.CALENDER_NO AS calenderNo, C.TITLE AS title, TO_CHAR(C.START_DATE, 'YYYY-MM-DD') AS startDate, TO_CHAR(C.START_DATE, 'HH24:MI') AS startTime, TO_CHAR(C.END_DATE, 'YYYY-MM-DD') AS endDate, TO_CHAR(C.END_DATE, 'HH24:MI') AS endTime FROM CALENDER C INNER JOIN CALENDERCONNECTION cc ON C.CALENDER_NO = cc.CALENDER_NO INNER JOIN USERS U ON cc.USER_NO = U.USER_NO WHERE U.COMPANY_NO = #{companyNo}
AND C.START_DATE < ADD_MONTHS( TO_DATE(#{year} || LPAD(#{month}, 2, '0'), 'YYYYMM'),1 ) AND C.END_DATE >= TO_DATE( #{year} || LPAD(#{month}, 2, '0'),'YYYYMM' )
ORDER BY startDate
